const int kBitsPerByte = 8;
const int kBitsPerInt64 = 64;
const int kBitsPerInt32 = 32;

int filter_size = (n * bits_per_key + kBitsPerByte - 1) / kBitsPerByte;
dst->resize(filter_size);
std::memset(&(*dst)[0], 0, filter_size);

std::vector<std::uint32_t> hash_seeds;
for (int i = 0; i < 3; i++) {
    hash_seeds.push_back(std::rand());
}

for (int i = 0; i < n; i++) {
    const Slice& key = keys[i];
    std::uint32_t hash1 = std::hash<std::string>{}(key.ToString());
    std::uint32_t hash2 = hash1;

    for (int j = 0; j < 3; j++) {
        hash1 += j * hash_seeds[j];
        hash2 += (j + 1) * hash_seeds[j];

        std::uint32_t bit_pos = hash1 % (filter_size * kBitsPerByte);
        std::uint32_t byte_pos = bit_pos / kBitsPerByte;
        std::uint32_t bit_in_byte = bit_pos % kBitsPerByte;

        (*dst)[byte_pos] |= (1 << bit_in_byte);
    }
}
// END_CODE

